import{_ as n,o as r,c as t,a3 as a}from"./chunks/framework.z_KJ15Ep.js";const s="/bilder/import-export-statistik/export-zk-daten-exportfenster.png",c=JSON.parse('{"title":"Daten zu Zentralen Klausuren exportieren","description":"","frontmatter":{"title":"Daten zu Zentralen Klausuren exportieren","source_pageid":929,"source_revision":5282},"headers":[],"relativePath":"schild3/import-export-statistik/zk-daten-verwaltung-export.md","filePath":"schild3/import-export-statistik/zk-daten-verwaltung-export.md"}'),i={name:"schild3/import-export-statistik/zk-daten-verwaltung-export.md"};function l(o,e,u,p,d,h){return r(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="daten-zu-zentralen-klausuren-exportieren" tabindex="-1">Daten zu Zentralen Klausuren exportieren <a class="header-anchor" href="#daten-zu-zentralen-klausuren-exportieren" aria-label="Permalink to &quot;Daten zu Zentralen Klausuren exportieren&quot;">​</a></h1><p>Wählen Sie Schuljahr, Abschnitt, Status und Jahrgänge für den Export der Klausurdaten. Auch Daten früherer Abschnitte können ausgegeben werden.</p><p><a href="/bilder/import-export-statistik/export-zk-daten-exportfenster.png"><img src="'+s+`" alt="Export der Daten für Zentrale Klausuren." loading="lazy"></a></p><p><em>Export der Daten für Zentrale Klausuren.</em></p><p>Über <em>Verwaltung ➜ Export</em> ➜ <strong>ZK-Daten</strong> lässt sich eine Datei erzeugen, in der die Daten für eine Zentrale Klausur enthalten sind.</p><p>Nach dem Aufruf der Funktion öffnet sich ein Fenster, in dem das zu exportierende <strong>Schuljahr mit dem Abschnitt</strong> zu wählen ist.</p><p>Da sich auch vergangene Abschnitte exportieren lassen, kann es sinnvoll sein, neben <em>aktiven</em> Schülern auch welche mit dem Status <em>Abgänger</em> und <em>Abschluss</em> auszulesen. Diese Wahl erfolgt über das Feld <strong>Aktueller Status der Schüler</strong>.</p><p><strong>Jahrgänge und Zielordner wählen</strong></p><p>Wählen Sie nun die zu exportierenden <strong>Jahrgänge</strong> aus. Es können per Haken auch mehrere Jahrgänge erzeugt werden.</p><p>Nach einer Wahl des Zielordners wird der Export über <strong>Daten exportieren</strong> gestartet.</p><p>Es wird eine Datei erzeugt, in deren Kopfzeile folgende durch ein Semikolon &quot;<strong>;</strong>&quot; getrennte Datenfelder enthalten sind:</p><pre><code> SchulNR
 Klasse
 ASDJahrgang
 SGL
 SchuelerNr
 Geschlecht
 FoerdSP1
 FoerdSP2
 PruefOrdn
 Fach
 Vornote
 NoteSchriftl
 NoteMuendl
 Note
 Kursart
 Bilingual
 Feststellungspruefung
 HSAbschluss
</code></pre><p>Diese Datei kann mit den üblichen Tabellenkalkulationsprogrammen geöffnet und weiterverarbeitet werden.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=ZK-Daten_(Verwaltung_Export)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 5282.</p>`,15)])])}const m=n(i,[["render",l]]);export{c as __pageData,m as default};
